AgentLaunchToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @title AgentLaunchToken — FANBEI (v3 deployment)
/// @notice ERC-20 token with a built-in Agent-ID-gated fair launch, modeled on the
///         public AgentLaunch mechanics used by BNB City / NiuLaiAI:
///         - fixed number of "shares"; first `freeShares` shares are free, 1 per Agent ID
///         - remaining shares are sold for native BNB at a fixed price, max 14 paid per Agent ID
///         - when all shares are gone, a PancakeSwap V2 pool is created in the same flow,
///           seeded with `liquidityBps` of the raise at 2x the mint price, LP burned
///         - if the deadline passes without sellout, paid buyers can refund 80%
///         - transfers are locked until the pool opens; after opening, pair trades
///           carry a buy/sell tax to the treasury (disclosed on the project site)
/// @dev    Self-contained, no imports, so the source verifies as a single file.
///         v3 deployment (翻倍 FANBEI, fanbei.fun) — same mechanics as the v1/v2
///         deployments with ONE change to the free lane: the unconditional
///         claimFree() is replaced by claimFreeWithVoucher(). A free claim now
///         requires an EIP-712 voucher from the project backend's attestor key,
///         issued only after the claimer posts the official FANBEI text to X.
///         The voucher binds (wallet, Agent ID, X username hash, X post ID hash,
///         deadline) under the EIP-712 domain "FANBEI Free Claim"; each Agent ID,
///         each X username and each X post may be used exactly once, enforced
///         on-chain. The attestor is owner-rotatable (setAttestor) and never
///         touches funds. Parameters: name "翻倍 FANBEI", symbol "FANBEI",
///         4,300 shares (1,300 free + 3,000 paid) at 0.00042 BNB/share, quota 14
///         paid per Agent ID (cap 15 total; raised from 9 by user decision
///         2026-11-02 19:57 WIB), 175,000 tokens/share, deadline 72h, liquidityBps
///         8000 (80% LP / 20% treasury), buy/sell tax 300/300 bps, refundBps
///         8000, team 60,000,000 tokens, reserve 40,000,000 tokens. Owner and
///         treasury are the project EOA 0x943B0e01c0c46B46b73fD641DF35EB7D06779037
///         and the attestor is 0x2E9849b9Cf5E054357C84DeE15C48C17893d8Fe1
///         (constructor arguments).
///         Derived allocations follow the unchanged v1 formulas:
///         publicAllocation = 4,300 x 175,000 = 752,500,000;
///         lpAllocation = 3,000 x 175,000 / 2 = 262,500,000 (at a full sellout,
///         210,000,000 are seeded at the 2x opening price and the remaining
///         52,500,000 are burned in the pool-open flow), so on-chain
///         totalSupply = 1,115,000,000.

interface IIdentityResolver {
    function identityOf(address user) external view returns (uint256);
}

interface IPancakeFactory {
    function createPair(address tokenA, address tokenB) external returns (address pair);
    function getPair(address tokenA, address tokenB) external view returns (address pair);
}

interface IPancakePair {
    function mint(address to) external returns (uint256 liquidity);
}

interface IWBNB {
    function deposit() external payable;
    function transfer(address to, uint256 value) external returns (bool);
}

contract AgentLaunchToken {
    // ------------------------------------------------------------------ ERC-20
    string public name;
    string public symbol;
    uint8 public constant decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    // ------------------------------------------------------------- launch data
    address public immutable owner;
    address public immutable treasury;
    IIdentityResolver public immutable identityResolver;

    uint256 public immutable price;          // wei per paid share
    uint256 public immutable maxShares;      // total shares (free + paid)
    uint256 public immutable freeShares;     // number of free shares (1 per Agent ID)
    uint256 public immutable quotaPerId;     // max paid shares per Agent ID (free is extra)
    uint256 public immutable tokensPerShare; // tokens per share
    uint256 public immutable liquidityBps;   // share of raise seeded into the pool
    uint256 public immutable buyTaxBps;
    uint256 public immutable sellTaxBps;
    uint256 public immutable refundBps;      // refunded share on failed launch
    uint256 public immutable startedAt;
    uint256 public immutable deadline;

    address public immutable wbnb;
    address public immutable pancakeFactory;
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;

    uint8 public phase; // 1 = sale, 3 = pool open, 4 = refund
    bool public paused;
    address public pair;

    uint256 public sold;        // paid shares sold
    uint256 public freeClaimed; // free shares claimed
    uint256 public raised;      // total wei raised from paid shares
    uint256 public refundOwed;  // outstanding refund obligations (phase 4)

    mapping(uint256 => bool) public freeClaimedById;
    mapping(bytes32 => bool) public usedXUsername; // keccak256(lowercase X username) already used for a free claim
    mapping(bytes32 => bool) public usedXPost;     // keccak256(X post id string) already used for a free claim
    mapping(uint256 => uint256) public paidById;
    mapping(address => uint256) public paidSharesOf;
    mapping(address => uint256) public contributionOf;
    mapping(address => bool) public refunded;

    uint256 public immutable lpAllocation;    // tokens reserved for the pool
    uint256 public immutable publicAllocation; // tokens reserved for share buyers

    // ------------------------------------------------------- free-claim voucher
    /// @notice Backend key allowed to sign free-claim vouchers. Holds no funds;
    ///         owner-rotatable via setAttestor() if the key is ever suspected.
    address public attestor;

    bytes32 public immutable DOMAIN_SEPARATOR; // EIP-712 domain "FANBEI Free Claim"
    bytes32 public constant VOUCHER_TYPEHASH =
        keccak256("FreeClaimVoucher(address wallet,uint256 agentId,bytes32 xUsernameHash,bytes32 xPostIdHash,uint256 voucherDeadline)");

    event FreeClaimed(address indexed user, uint256 indexed agentId, uint256 tokenAmount);
    event VoucherUsed(uint256 indexed agentId, bytes32 xUsernameHash, bytes32 xPostIdHash);
    event AttestorChanged(address indexed oldAttestor, address indexed newAttestor);
    event Minted(address indexed user, uint256 indexed agentId, uint256 shares, uint256 cost);
    event PoolOpened(address indexed pair, uint256 bnbSeeded, uint256 tokensSeeded, uint256 treasuryCut);
    event Refunded(address indexed user, uint256 amount);
    event PhaseChanged(uint8 phase);

    error NoAgentId();
    error AlreadyClaimed();
    error FreeSoldOut();
    error BadVoucher();
    error VoucherExpired();
    error XUsernameUsed();
    error XPostUsed();
    error SoldOutError();
    error BadQuantity();
    error QuotaExceeded();
    error WrongPhase();
    error AfterDeadline();
    error BeforeDeadline();
    error TradingLocked();
    error PausedError();
    error NotOwner();
    error NothingToRefund();
    error TransferFailed();

    bool private _entered;
    modifier nonReentrant() {
        require(!_entered, "REENTRANCY");
        _entered = true;
        _;
        _entered = false;
    }
    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    /// @param _priceWeiPerShare  e.g. 420000000000000 wei = 0.00042 BNB (~$0.30 at BNB $714)
    /// @param _wbnb              mainnet BSC: 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c
    /// @param _pancakeFactory    mainnet BSC: 0xcA143Ce32Fe78f1f7019d7d551a6402fC5350c73
    constructor(
        string memory _name,
        string memory _symbol,
        address _identityResolver,
        address _wbnb,
        address _pancakeFactory,
        uint256 _priceWeiPerShare,
        uint256 _maxShares,
        uint256 _freeShares,
        uint256 _quotaPerId,
        uint256 _tokensPerShare,
        uint256 _liquidityBps,
        uint256 _buyTaxBps,
        uint256 _sellTaxBps,
        uint256 _refundBps,
        uint256 _saleDurationSeconds,
        uint256 _teamTokens,
        uint256 _reserveTokens,
        address _owner,
        address _treasury,
        address _attestor
    ) {
        name = _name;
        symbol = _symbol;
        owner = _owner;
        treasury = _treasury;
        attestor = _attestor;
        // EIP-712 domain separator for free-claim vouchers (design §5.1):
        // name "FANBEI Free Claim", version "1", this chain, this contract.
        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256(bytes("FANBEI Free Claim")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
        identityResolver = IIdentityResolver(_identityResolver);
        wbnb = _wbnb;
        pancakeFactory = _pancakeFactory;

        price = _priceWeiPerShare;
        maxShares = _maxShares;
        freeShares = _freeShares;
        quotaPerId = _quotaPerId;
        tokensPerShare = _tokensPerShare;
        liquidityBps = _liquidityBps;
        buyTaxBps = _buyTaxBps;
        sellTaxBps = _sellTaxBps;
        refundBps = _refundBps;
        startedAt = block.timestamp;
        deadline = block.timestamp + _saleDurationSeconds;

        publicAllocation = _maxShares * _tokensPerShare;
        // Pool seeding at the 2x opening price, for a full sellout at 100% liquidity:
        // lpTokens(max) = (paidShares * price) * tokensPerShare / (2 * price)
        //               = paidShares * tokensPerShare / 2
        uint256 paidSharesTotal = _maxShares - _freeShares;
        lpAllocation = (paidSharesTotal * _tokensPerShare) / 2;

        totalSupply = publicAllocation + lpAllocation + _teamTokens + _reserveTokens;
        balanceOf[address(this)] = publicAllocation + lpAllocation;
        balanceOf[treasury] = _teamTokens + _reserveTokens;
        emit Transfer(address(0), address(this), publicAllocation + lpAllocation);
        emit Transfer(address(0), treasury, _teamTokens + _reserveTokens);

        phase = 1;
        emit PhaseChanged(1);
    }

    // ------------------------------------------------------------------- views
    struct Info {
        string name;
        string symbol;
        address treasury;
        address quote;
        bool native;
        address pair;
        uint256 price;
        uint256 maxShares;
        uint256 freeShares;
        uint256 quotaPerId;
        uint256 tokensPerShare;
        uint256 liquidityBps;
        uint256 buyTaxBps;
        uint256 sellTaxBps;
        uint256 refundBps;
        uint256 startedAt;
        uint256 deadline;
        uint256 sold;
        uint256 freeClaimed;
        uint8 phase;
    }

    function info() external view returns (Info memory i) {
        i.name = name;
        i.symbol = symbol;
        i.treasury = treasury;
        i.quote = wbnb;
        i.native = true;
        i.pair = pair;
        i.price = price;
        i.maxShares = maxShares;
        i.freeShares = freeShares;
        i.quotaPerId = quotaPerId;
        i.tokensPerShare = tokensPerShare;
        i.liquidityBps = liquidityBps;
        i.buyTaxBps = buyTaxBps;
        i.sellTaxBps = sellTaxBps;
        i.refundBps = refundBps;
        i.startedAt = startedAt;
        i.deadline = deadline;
        i.sold = sold;
        i.freeClaimed = freeClaimed;
        i.phase = phase;
    }

    struct UserInfo {
        uint256 id;
        uint256 remaining;
        bool freeClaimed;
        uint256 paidShares;
    }

    function userInfo(address user) external view returns (UserInfo memory) {
        uint256 id = identityResolver.identityOf(user);
        uint256 paid = paidById[id];
        return UserInfo({
            id: id,
            remaining: id == 0 ? 0 : (paid >= quotaPerId ? 0 : quotaPerId - paid),
            freeClaimed: id == 0 ? false : freeClaimedById[id],
            paidShares: paid
        });
    }

    function totalSoldShares() public view returns (uint256) {
        return sold + freeClaimed;
    }

    // -------------------------------------------------------------- sale logic
    /// @notice Claim the one free share for an Agent ID. Requires a voucher from
    ///         the project backend (issued after the official FANBEI post on X
    ///         is verified): an EIP-712 signature by `attestor` over
    ///         (wallet, agentId, xUsernameHash, xPostIdHash, voucherDeadline)
    ///         under the domain "FANBEI Free Claim". Each Agent ID, X username
    ///         and X post can be used exactly once, enforced here on-chain.
    /// @param xUsernameHash  keccak256(abi.encodePacked(lowercase X username))
    /// @param xPostIdHash    keccak256(abi.encodePacked(X post id string))
    function claimFreeWithVoucher(
        uint256 agentId,
        bytes32 xUsernameHash,
        bytes32 xPostIdHash,
        uint256 voucherDeadline,
        bytes calldata signature
    ) external nonReentrant {
        if (paused) revert PausedError();
        if (phase != 1) revert WrongPhase();
        if (block.timestamp > deadline) revert AfterDeadline();
        // Wallet <-> Agent ID binding is read from the resolver, never trusted
        // from the caller's input.
        uint256 id = identityResolver.identityOf(msg.sender);
        if (id == 0) revert NoAgentId();
        if (id != agentId) revert BadVoucher();
        if (voucherDeadline < block.timestamp) revert VoucherExpired();
        if (freeClaimedById[id]) revert AlreadyClaimed();
        if (usedXUsername[xUsernameHash]) revert XUsernameUsed();
        if (usedXPost[xPostIdHash]) revert XPostUsed();
        if (freeClaimed >= freeShares) revert FreeSoldOut();

        bytes32 structHash = keccak256(
            abi.encode(VOUCHER_TYPEHASH, msg.sender, agentId, xUsernameHash, xPostIdHash, voucherDeadline)
        );
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, structHash));
        if (_recover(digest, signature) != attestor) revert BadVoucher();

        freeClaimedById[id] = true;
        usedXUsername[xUsernameHash] = true;
        usedXPost[xPostIdHash] = true;
        freeClaimed += 1;
        _distribute(msg.sender, tokensPerShare);
        emit FreeClaimed(msg.sender, id, tokensPerShare);
        emit VoucherUsed(id, xUsernameHash, xPostIdHash);
        if (totalSoldShares() >= maxShares) _openPool();
    }

    /// @notice Rotate the free-claim voucher signer. Only affects who may sign
    ///         future vouchers; never touches funds, balances or the phase.
    function setAttestor(address newAttestor) external onlyOwner {
        require(newAttestor != address(0), "ZERO_ATTESTOR");
        emit AttestorChanged(attestor, newAttestor);
        attestor = newAttestor;
    }

    function _recover(bytes32 digest, bytes calldata signature) internal pure returns (address) {
        if (signature.length != 65) return address(0);
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := calldataload(signature.offset)
            s := calldataload(add(signature.offset, 32))
            v := byte(0, calldataload(add(signature.offset, 64)))
        }
        if (v < 27) v += 27;
        if (v != 27 && v != 28) return address(0);
        return ecrecover(digest, v, r, s);
    }

    function mint(uint256 requested) external payable nonReentrant {
        if (paused) revert PausedError();
        if (phase != 1) revert WrongPhase();
        if (block.timestamp > deadline) revert AfterDeadline();
        if (requested == 0) revert BadQuantity();
        uint256 id = identityResolver.identityOf(msg.sender);
        if (id == 0) revert NoAgentId();
        if (paidById[id] + requested > quotaPerId) revert QuotaExceeded();
        if (totalSoldShares() + requested > maxShares) revert SoldOutError();
        uint256 cost = requested * price;
        require(msg.value == cost, "EXACT_PAYMENT_REQUIRED");

        paidById[id] += requested;
        paidSharesOf[msg.sender] += requested;
        contributionOf[msg.sender] += cost;
        sold += requested;
        raised += cost;
        _distribute(msg.sender, requested * tokensPerShare);
        emit Minted(msg.sender, id, requested, cost);
        if (totalSoldShares() >= maxShares) _openPool();
    }

    /// @notice Anyone can move a failed sale into the refund phase after the deadline.
    function finalizeRefund() external {
        if (phase != 1) revert WrongPhase();
        if (block.timestamp <= deadline) revert BeforeDeadline();
        if (totalSoldShares() >= maxShares) revert SoldOutError();
        phase = 4;
        refundOwed = (raised * refundBps) / 10000;
        emit PhaseChanged(4);
    }

    /// @notice Paid buyers reclaim refundBps of their contribution; their paid
    ///         tokens are clawed back to the contract. Free tokens simply stay
    ///         locked forever because trading never opens.
    function refund() external nonReentrant {
        if (phase != 4) revert WrongPhase();
        if (refunded[msg.sender]) revert NothingToRefund();
        uint256 shares = paidSharesOf[msg.sender];
        if (shares == 0) revert NothingToRefund();
        uint256 amount = (contributionOf[msg.sender] * refundBps) / 10000;

        refunded[msg.sender] = true;
        paidSharesOf[msg.sender] = 0;
        contributionOf[msg.sender] = 0;
        refundOwed -= amount;

        uint256 clawback = shares * tokensPerShare;
        require(balanceOf[msg.sender] >= clawback, "TOKENS_MOVED");
        balanceOf[msg.sender] -= clawback;
        balanceOf[address(this)] += clawback;
        emit Transfer(msg.sender, address(this), clawback);

        (bool ok, ) = msg.sender.call{value: amount}("");
        if (!ok) revert TransferFailed();
        emit Refunded(msg.sender, amount);
    }

    /// @notice Owner withdraws the non-refundable residue in the refund phase,
    ///         never touching funds owed to pending refunders.
    function withdrawResidue() external onlyOwner nonReentrant {
        if (phase != 4) revert WrongPhase();
        uint256 bal = address(this).balance;
        require(bal > refundOwed, "NOTHING_TO_WITHDRAW");
        uint256 amount = bal - refundOwed;
        (bool ok, ) = treasury.call{value: amount}("");
        if (!ok) revert TransferFailed();
    }

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
    }

    // -------------------------------------------------------------- pool open
    function _openPool() internal {
        phase = 3;
        emit PhaseChanged(3);

        uint256 lpBnb = (raised * liquidityBps) / 10000;
        uint256 treasuryCut = raised - lpBnb;
        uint256 lpTokens = (lpBnb * tokensPerShare) / (2 * price);
        require(lpTokens <= lpAllocation, "LP_ALLOCATION_SHORT");

        pair = IPancakeFactory(pancakeFactory).createPair(address(this), wbnb);

        // Wrap the seed BNB and move both sides into the pair, then mint LP to the
        // burn address: liquidity is locked forever.
        IWBNB(wbnb).deposit{value: lpBnb}();
        require(IWBNB(wbnb).transfer(pair, lpBnb), "WBNB_TRANSFER_FAILED");
        balanceOf[address(this)] -= lpTokens;
        balanceOf[pair] += lpTokens;
        emit Transfer(address(this), pair, lpTokens);
        IPancakePair(pair).mint(BURN);

        // Burn LP-allocation leftovers so no hidden supply stays in the contract.
        uint256 leftover = lpAllocation - lpTokens;
        if (leftover > 0) {
            balanceOf[address(this)] -= leftover;
            balanceOf[BURN] += leftover;
            emit Transfer(address(this), BURN, leftover);
        }

        if (treasuryCut > 0) {
            (bool ok, ) = treasury.call{value: treasuryCut}("");
            if (!ok) revert TransferFailed();
        }
        emit PoolOpened(pair, lpBnb, lpTokens, treasuryCut);
    }

    // --------------------------------------------------------------- transfers
    function _distribute(address to, uint256 amount) internal {
        balanceOf[address(this)] -= amount;
        balanceOf[to] += amount;
        emit Transfer(address(this), to, amount);
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        require(allowed >= amount, "ALLOWANCE");
        if (allowed != type(uint256).max) {
            allowance[from][msg.sender] = allowed - amount;
        }
        _transfer(from, to, amount);
        return true;
    }

    function _transfer(address from, address to, uint256 amount) internal {
        if (phase != 3) revert TradingLocked();
        require(balanceOf[from] >= amount, "BALANCE");
        require(to != address(0), "ZERO_TO");

        uint256 tax = 0;
        bool exempt = from == treasury || to == treasury || from == address(this) || to == address(this);
        if (!exempt && pair != address(0)) {
            if (from == pair) {
                tax = (amount * buyTaxBps) / 10000;
            } else if (to == pair) {
                tax = (amount * sellTaxBps) / 10000;
            }
        }

        balanceOf[from] -= amount;
        if (tax > 0) {
            balanceOf[treasury] += tax;
            emit Transfer(from, treasury, tax);
        }
        balanceOf[to] += amount - tax;
        emit Transfer(from, to, amount - tax);
    }

    receive() external payable {}
}

AGIOMint.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {IPancakeFactory, IPancakePair, PancakeMath} from "./interfaces/IPancake.sol";
import {AGIOToken} from "./AGIOToken.sol";

interface IAgentHandles {
    function ownerOf(uint256 tokenId) external view returns (address);
    function handleOf(address owner) external view returns (string memory);
}

interface IBNBUsdFeed {
    function decimals() external view returns (uint8);
    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80);
}

interface IWBNB {
    function deposit() external payable;
    function withdraw(uint256 amount) external;
}

contract AGIOMint is ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant TOTAL_SHARES = 10_000;
    uint256 public constant MAX_SUPPLY = 1_000_000_000 ether;
    uint256 public constant OPEN_AT = 10_000;
    uint256 public constant USER_SHARE = 57_000 ether;
    uint256 public constant POOL_SHARE = 38_000 ether;
    uint256 public constant TREASURY_TOKENS = 50_000_000 ether;
    uint256 public constant OPEN_USDT = 8_000 ether;
    uint256 public constant OPEN_TOKENS = OPEN_AT * POOL_SHARE;
    uint256 public constant TREASURY_BPS = 2_000;
    uint256 public constant TAX_SWAP_BPS = 10;
    uint256 public constant BNB_EXTRA_BPS = 100;
    uint256 public constant BASE_PER_ID = 25;
    uint256 public constant MAX_PER_TX = 25;
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;

    bytes32 public constant TASK_FOLLOW = keccak256("FOLLOW");
    bytes32 public constant TASK_TWEET = keccak256("TWEET");
    bytes32 public constant TASK_TELEGRAM = keccak256("TELEGRAM");
    bytes32 public constant REASON_INVITE = keccak256("INVITE");
    bytes32 public constant REASON_SOCIALS = keccak256("SOCIALS");
    bytes32 public constant FREE_MINT_REPOST_COMMENT = keccak256("REPOST_COMMENT");
    bytes32 public constant FREE_MINT_AVATAR = keccak256("AVATAR");
    bytes32 private constant SOCIAL_TYPEHASH =
        keccak256("Social(address user,bytes32 task,bytes32 account,uint256 deadline)");
    bytes32 private constant SOCIALS_TYPEHASH =
        keccak256("Socials(address user,uint256 agentTokenId,uint256 extra,uint256 nonce,uint256 deadline)");
    bytes32 private constant FREE_MINT_TYPEHASH =
        keccak256("FreeMint(address user,uint256 agentTokenId,bytes32 task)");
    bytes32 private constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");

    AGIOToken public immutable token;
    IERC20 public immutable usdt;
    IPancakePair public immutable pair;
    IPancakePair public immutable wbnbPair;
    address public immutable wbnb;
    IAgentHandles public immutable registrar;
    IBNBUsdFeed public immutable feed;
    address public treasury;
    address public vault;
    address public immutable deployer;
    address public immutable owner;
    address public quotaSigner;
    uint256 public immutable swapFeeBps;
    uint256 public immutable feedHeartbeat;
    uint256 public immutable feedMin;
    uint256 public immutable feedMax;
    bool private immutable _usdtIs0;

    uint256 public totalMinted;
    uint256 public totalPaid;
    bool public paused = true;
    bool public renounced;
    uint256 public pendingUsdt;
    uint256 public pendingTokens;
    uint256 public openedTime;
    uint256 public lastTaxSwapBlock;

    mapping(uint256 => uint256) public mintedCount;
    mapping(uint256 => uint256) public extraQuota;
    mapping(address => mapping(uint256 => bool)) public socialNonces;
    mapping(uint256 => bool) public paidOnce;
    mapping(uint256 => mapping(bytes32 => bool)) public socialDone;
    mapping(uint256 => mapping(bytes32 => bool)) public freeMintDone;
    mapping(bytes32 => uint256) public accountAgent;
    mapping(address => bool) public unblockable;

    event PausedSet(bool paused);
    event Renounced();
    event Minted(address indexed minter, uint256 indexed agentTokenId, uint256 firstSerial, uint256 shares, uint256 paid);
    event QuotaGranted(address indexed user, uint256 indexed agentTokenId, uint256 extra, bytes32 reason);
    event SocialsClaimed(address indexed user, uint256 indexed agentTokenId, uint256 extra, uint256 nonce);
    event Refunded(address indexed recipient, uint256 amount);
    event Opened(uint256 usdtIn, uint256 tokensIn, uint256 lp);
    event PoolOpenFailed(bytes reason);
    event QuotaSignerSet(address signer);
    event FreeMintClaimed(address indexed user, uint256 indexed agentTokenId, bytes32 indexed task);
    event TaxSwapped(uint256 tokensIn, uint256 usdtOut);
    event TaxSwapFailed(bytes reason);

    error NotOwner();
    error InsufficientLiquidityFunding(uint256 available, uint256 required);
    error NotSeeded();
    error Paused();
    error AdminRenounced();
    error BadShares();
    error SoldOut();
    error NoAgent();
    error Quota();
    error OverMaxCost();
    error BadPayment();
    error StalePrice();
    error SwapShort();
    error RefundFailed();
    error AlreadyGranted();
    error BadTask();
    error BadSignature();
    error NotBlockable();
    error NotOpen();
    error NothingToSwap();
    error SwappedThisBlock();
    error ZeroAddress();
    error BadConfiguration();
    error AlreadyOpen();
    error OnlySelf();

    struct Config {
        address token;
        address registrar;
        address treasury;
        address owner;
        address quotaSigner;
        address feed;
        address wbnb;
        address factory;
        uint256 swapFeeBps;
        uint256 feedHeartbeat;
        uint256 feedMin;
        uint256 feedMax;
        address[] unblockable;
    }

    constructor(Config memory c) {
        if (
            c.token == address(0) || c.registrar == address(0) || c.treasury == address(0)
                || c.quotaSigner == address(0) || c.feed == address(0) || c.wbnb == address(0)
                || c.factory == address(0) || c.owner == address(0)
        ) revert ZeroAddress();
        if (c.swapFeeBps >= 10_000 || c.feedHeartbeat == 0 || c.feedMin == 0 || c.feedMax < c.feedMin) {
            revert BadConfiguration();
        }
        token = AGIOToken(c.token);
        usdt = IERC20(token.usdt());
        pair = IPancakePair(token.pair());
        if (IPancakeFactory(c.factory).getPair(c.token, address(usdt)) != address(pair)) revert BadConfiguration();
        wbnb = c.wbnb;
        wbnbPair = IPancakePair(IPancakeFactory(c.factory).getPair(address(usdt), c.wbnb));
        if (address(wbnbPair) == address(0)) revert ZeroAddress();
        registrar = IAgentHandles(c.registrar);
        feed = IBNBUsdFeed(c.feed);
        treasury = c.treasury;
        deployer = msg.sender;
        owner = c.owner;
        quotaSigner = c.quotaSigner;
        swapFeeBps = c.swapFeeBps;
        feedHeartbeat = c.feedHeartbeat;
        feedMin = c.feedMin;
        feedMax = c.feedMax;
        _usdtIs0 = pair.token0() == address(usdt);
        for (uint256 i; i < c.unblockable.length; i++) unblockable[c.unblockable[i]] = true;
    }

    receive() external payable {
        if (msg.sender != wbnb) revert BadPayment();
    }

    function priceCents(uint256) public pure returns (uint256) {
        return 100;
    }

    function costOf(uint256 shares) public view returns (uint256 cost) {
        uint256 n = totalMinted;
        for (uint256 i; i < shares; i++) cost += priceCents(n + 1 + i) * 1e16;
    }

    function quotaOf(uint256 id) public view returns (uint256) { return BASE_PER_ID + extraQuota[id]; }
    function opened() public view returns (bool) { return openedTime != 0; }

    function reserves() public view returns (uint256 rUsdt, uint256 rToken) {
        (uint112 r0, uint112 r1,) = pair.getReserves();
        (rUsdt, rToken) = _usdtIs0 ? (uint256(r0), uint256(r1)) : (uint256(r1), uint256(r0));
    }

    function circulating() public view returns (uint256) {
        return token.totalSupply() - token.balanceOf(address(pair)) - token.balanceOf(DEAD)
            - token.balanceOf(address(this));
    }

    function bnbQuote(uint256 shares) public view returns (uint256) { return _bnbFor(costOf(shares)); }

    function _onlyOwner() private view {
        if (msg.sender != owner) revert NotOwner();
        if (renounced) revert AdminRenounced();
    }

    function setPaused(bool next) external {
        _onlyOwner();
        paused = next;
        emit PausedSet(next);
    }

    function refund(address recipient, uint256 amount) external nonReentrant {
        _onlyOwner();
        usdt.safeTransfer(recipient, amount);
        emit Refunded(recipient, amount);
    }

    function setTreasury(address next) external {
        _onlyOwner();
        treasury = next;
    }

    function setVault(address next) external {
        _onlyOwner();
        vault = next;
    }

    function setQuotaSigner(address next) external {
        _onlyOwner();
        quotaSigner = next;
        emit QuotaSignerSet(next);
    }

    function openPool() external nonReentrant {
        _onlyOwner();
        _open();
    }

    function openPoolFromMint() external {
        if (msg.sender != address(this)) revert OnlySelf();
        _open();
    }

    function setPoolBlocked(address pool, bool blocked) external {
        _onlyOwner();
        if (
            pool == address(pair) || pool == address(this) || pool == treasury || pool == address(token)
                || pool == DEAD || unblockable[pool] || pool.code.length == 0 || _is7702(pool)
        ) revert NotBlockable();
        token.setPoolBlocked(pool, blocked);
    }

    function renounce() external {
        _onlyOwner();
        renounced = true;
        paused = false;
        token.disableBlocks();
        emit Renounced();
    }

    function _is7702(address a) private view returns (bool) {
        if (a.code.length != 23) return false;
        bytes memory code = a.code;
        return code[0] == 0xef && code[1] == 0x01 && code[2] == 0x00;
    }

    function claimSocial(bytes32 task, bytes32 account, uint256 deadline, bytes calldata signature) external {
        if (block.timestamp > deadline) revert BadSignature();
        if (task != TASK_FOLLOW && task != TASK_TWEET && task != TASK_TELEGRAM) revert BadTask();
        bytes32 domain = keccak256(
            abi.encode(DOMAIN_TYPEHASH, keccak256("AGIOMint"), keccak256("1"), block.chainid, address(this))
        );
        bytes32 digest = keccak256(abi.encodePacked(
            "\x19\x01", domain, keccak256(abi.encode(SOCIAL_TYPEHASH, msg.sender, task, account, deadline))
        ));
        (address got, ECDSA.RecoverError err,) = ECDSA.tryRecover(digest, signature);
        if (err != ECDSA.RecoverError.NoError || got != quotaSigner) revert BadSignature();
        (uint256 id, bool ok) = _agent(msg.sender);
        if (!ok) revert NoAgent();
        if (socialDone[id][task]) revert AlreadyGranted();
        uint256 bound = accountAgent[account];
        if (bound != 0 && bound != id) revert AlreadyGranted();
        socialDone[id][task] = true;
        accountAgent[account] = id;
        extraQuota[id] += 1;
        emit QuotaGranted(msg.sender, id, 1, task);
    }

    function claimSocials(
        uint256 agentTokenId,
        uint256 extra,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) external {
        if (block.timestamp > deadline) revert BadSignature();
        if (socialNonces[msg.sender][nonce]) revert AlreadyGranted();
        (uint256 id, bool ok) = _agent(msg.sender);
        if (!ok || id != agentTokenId) revert NoAgent();
        bytes32 domain = keccak256(
            abi.encode(DOMAIN_TYPEHASH, keccak256("AGIOMint"), keccak256("1"), block.chainid, address(this))
        );
        bytes32 digest = keccak256(abi.encodePacked(
            "\x19\x01", domain,
            keccak256(abi.encode(SOCIALS_TYPEHASH, msg.sender, agentTokenId, extra, nonce, deadline))
        ));
        (address got, ECDSA.RecoverError err,) = ECDSA.tryRecover(digest, signature);
        if (err != ECDSA.RecoverError.NoError || got != quotaSigner) revert BadSignature();
        socialNonces[msg.sender][nonce] = true;
        extraQuota[id] += extra;
        emit QuotaGranted(msg.sender, id, extra, REASON_SOCIALS);
        emit SocialsClaimed(msg.sender, id, extra, nonce);
    }

    function _agent(address from) internal view returns (uint256 id, bool ok) {
        try registrar.handleOf(from) returns (string memory handle) {
            if (bytes(handle).length == 0) return (0, false);
            id = uint256(keccak256(bytes(handle)));
            try registrar.ownerOf(id) returns (address owner) { ok = owner == from; }
            catch { ok = false; }
        } catch { ok = false; }
    }

    function _creditInvite(address from, uint256 id, address referrer) private {
        if (referrer == address(0) || referrer == from) return;
        (uint256 rid, bool rok) = _agent(referrer);
        if (!rok || rid == id) return;
        extraQuota[rid] += 1;
        emit QuotaGranted(referrer, rid, 1, REASON_INVITE);
    }

    function mint(uint256 shares, address referrer, uint256 maxCost) external nonReentrant {
        uint256 id = _check(shares);
        uint256 cost = costOf(shares);
        if (cost > maxCost) revert OverMaxCost();
        usdt.safeTransferFrom(msg.sender, address(this), cost);
        _mintShares(id, shares, cost, 0, referrer);
    }

    function freeMint(bytes32 task, uint256 agentTokenId, bytes calldata signature) external nonReentrant {
        uint256 id = _check(1);
        if (id != agentTokenId) revert NoAgent();
        if (task != FREE_MINT_REPOST_COMMENT && task != FREE_MINT_AVATAR) revert BadTask();
        if (freeMintDone[id][task]) revert AlreadyGranted();
        bytes32 domain = keccak256(
            abi.encode(DOMAIN_TYPEHASH, keccak256("AGIOMint"), keccak256("1"), block.chainid, address(this))
        );
        bytes32 digest = keccak256(abi.encodePacked(
            "\x19\x01", domain, keccak256(abi.encode(FREE_MINT_TYPEHASH, msg.sender, id, task))
        ));
        (address got, ECDSA.RecoverError err,) = ECDSA.tryRecover(digest, signature);
        if (err != ECDSA.RecoverError.NoError || got != quotaSigner) revert BadSignature();
        freeMintDone[id][task] = true;
        _mintShares(id, 1, 0, 0, address(0));
        emit FreeMintClaimed(msg.sender, id, task);
    }

    function mintWithBnb(uint256 shares, address referrer, uint256 maxCost) external payable nonReentrant {
        uint256 id = _check(shares);
        uint256 cost = costOf(shares);
        uint256 need = _bnbFor(cost);
        if (need > maxCost) revert OverMaxCost();
        if (msg.value < need) revert BadPayment();
        uint256 got = _swapBnbForUsdt(need);
        if (got < cost) revert SwapShort();
        _mintShares(id, shares, cost, got - cost, referrer);
        uint256 refund = msg.value - need;
        if (refund > 0) {
            (bool ok,) = msg.sender.call{value: refund}("");
            if (!ok) revert RefundFailed();
        }
    }

    function _check(uint256 shares) private view returns (uint256 id) {
        if (paused) revert Paused();
        if (shares == 0 || shares > MAX_PER_TX) revert BadShares();
        if (totalMinted + shares > TOTAL_SHARES) revert SoldOut();
        bool ok;
        (id, ok) = _agent(msg.sender);
        if (!ok) revert NoAgent();
        if (mintedCount[id] + shares > quotaOf(id)) revert Quota();
    }

    function _mintShares(uint256 id, uint256 shares, uint256 cost, uint256 extraUsdt, address referrer) private {
        mintedCount[id] += shares;
        if (cost > 0 && !paidOnce[id]) {
            paidOnce[id] = true;
            _creditInvite(msg.sender, id, referrer);
        }
        uint256 first = totalMinted + 1;
        uint256 cut = cost * TREASURY_BPS / 10_000;
        totalMinted += shares;
        totalPaid += cost;
        pendingUsdt += cost - cut;
        uint256 poolTokens = shares * POOL_SHARE;
        pendingTokens += poolTokens;
        token.mint(address(this), poolTokens);
        token.mint(msg.sender, shares * USER_SHARE);
        if (cut + extraUsdt > 0) usdt.safeTransfer(treasury, cut + extraUsdt);
        if (totalMinted == OPEN_AT) {
            token.mint(treasury, TREASURY_TOKENS);
            try this.openPoolFromMint() {}
            catch (bytes memory why) { emit PoolOpenFailed(why); }
        }
        emit Minted(msg.sender, id, first, shares, cost);
    }

    function _open() private {
        if (opened()) revert AlreadyOpen();
        if (totalMinted != OPEN_AT || pendingTokens != OPEN_TOKENS) revert NotSeeded();
        uint256 balance = usdt.balanceOf(address(this));
        if (balance < OPEN_USDT) revert InsufficientLiquidityFunding(balance, OPEN_USDT);
        pendingUsdt = 0;
        pendingTokens = 0;
        usdt.safeTransfer(address(pair), OPEN_USDT);
        IERC20(address(token)).safeTransfer(address(pair), OPEN_TOKENS);
        uint256 lp = pair.mint(DEAD);
        token.enableTrading();
        pair.sync();
        openedTime = block.timestamp;
        emit Opened(OPEN_USDT, OPEN_TOKENS, lp);
    }

    function _bnbFor(uint256 usdAmount) private view returns (uint256) {
        (, int256 answer,, uint256 updatedAt,) = feed.latestRoundData();
        if (answer <= 0 || updatedAt == 0 || updatedAt > block.timestamp || block.timestamp > updatedAt + feedHeartbeat) {
            revert StalePrice();
        }
        uint256 px = uint256(answer);
        if (px < feedMin || px > feedMax) revert StalePrice();
        uint256 withExtra = usdAmount * (10_000 + BNB_EXTRA_BPS) / 10_000;
        return (withExtra * 10 ** feed.decimals() + px - 1) / px;
    }

    function _swapBnbForUsdt(uint256 bnbIn) private returns (uint256 usdtOut) {
        IWBNB(wbnb).deposit{value: bnbIn}();
        IERC20(wbnb).safeTransfer(address(wbnbPair), bnbIn);
        uint256 before = usdt.balanceOf(address(this));
        _swapOn(wbnbPair, wbnb, address(this));
        usdtOut = usdt.balanceOf(address(this)) - before;
    }

    function _swapOn(IPancakePair lp, address tokenIn, address to) private {
        (uint112 r0, uint112 r1,) = lp.getReserves();
        bool inIs0 = lp.token0() == tokenIn;
        (uint256 rIn, uint256 rOut) = inIs0 ? (uint256(r0), uint256(r1)) : (uint256(r1), uint256(r0));
        uint256 actualIn = IERC20(tokenIn).balanceOf(address(lp)) - rIn;
        uint256 out = PancakeMath.amountOut(actualIn, rIn, rOut, swapFeeBps);
        (uint256 out0, uint256 out1) = inIs0 ? (uint256(0), out) : (out, uint256(0));
        lp.swap(out0, out1, to, "");
    }

    function swapTax() external nonReentrant {
        if (!opened()) revert NotOpen();
        if (lastTaxSwapBlock == block.number) revert SwappedThisBlock();
        _swapTax();
    }

    function swapTaxFromToken() external {
        if (lastTaxSwapBlock == block.number) return;
        try this.swapTax() {}
        catch (bytes memory why) { emit TaxSwapFailed(why); }
    }

    function _swapTax() private {
        (, uint256 rToken) = reserves();
        uint256 amount = token.balanceOf(address(this));
        uint256 cap = rToken * TAX_SWAP_BPS / 10_000;
        if (amount > cap) amount = cap;
        if (amount == 0) revert NothingToSwap();
        lastTaxSwapBlock = block.number;
        uint256 before = usdt.balanceOf(address(this));
        IERC20(address(token)).safeTransfer(address(pair), amount);
        _swapOn(pair, address(token), address(this));
        uint256 usdtOut = usdt.balanceOf(address(this)) - before;
        uint256 vaultUsdt = usdtOut / 2;
        usdt.safeTransfer(treasury, usdtOut - vaultUsdt);
        usdt.safeTransfer(vault, vaultUsdt);
        emit TaxSwapped(amount, usdtOut);
    }
}

